+test("RF-005: anular devuelve una factura nueva con motivo y no altera la original", () => {
+  const original = emitirFactura({ numero: 8, nit: "1023456", razonSocial: "Cliente SA", items: [{ cantidad: 1, precioUnitarioCentavos: 1000 }] });
+  const anulada = anularFactura(original, "Error en el NIT");
+  assert.notEqual(anulada, original);
+  assert.equal(anulada.estado, "anulada");
+  assert.equal(anulada.motivoAnulacion, "Error en el NIT");
+  assert.equal(anulada.numero, original.numero);
+  assert.equal(anulada.totalCentavos, original.totalCentavos);
+  assert.ok(Object.isFrozen(anulada));
+  assert.equal(original.estado, "emitida");
+  assert.equal(original.motivoAnulacion, undefined);
+});
+
+test("RF-005: anular sin motivo se rechaza", () => {
+  const f = emitirFactura({ numero: 9, nit: "1023456", razonSocial: "Cliente SA", items: [{ cantidad: 1, precioUnitarioCentavos: 1000 }] });
+  assert.throws(() => anularFactura(f, ""));
+  assert.throws(() => anularFactura(f, "   "));
+  assert.throws(() => anularFactura(f));
+});
+
+test("RF-005: solo se anula una factura emitida", () => {
